<style>
.xd6-projects-page{padding:0 0 80px;background:#101012;color:#f7f7f8}
.xd6-projects-container{width:min(1240px,calc(100% - 64px));margin-inline:auto}
.xd6-projects-breadcrumb{display:flex;flex-wrap:wrap;gap:12px;padding:26px 0;color:#aeb0b9;font-size:12px}
.xd6-projects-breadcrumb a{color:#d6d7dc}.xd6-projects-breadcrumb a:hover{color:#ff827b}
.xd6-projects-heading{padding:18px 0 36px;margin-bottom:36px;border-bottom:1px solid #333339}
.xd6-projects-kicker{display:flex;align-items:center;gap:12px;margin:0 0 16px;color:#ff827b;font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}
.xd6-projects-kicker:before{content:'';width:28px;height:3px;background:#ff3b30}
.xd6-projects-heading h1{color:#fff;font-size:clamp(36px,4vw,52px);font-weight:700;line-height:1.15;letter-spacing:-.025em;margin:0 0 18px}
.xd6-projects-heading>p:last-child{max-width:700px;margin:0;color:#c3c3ca;font-size:16px;line-height:1.8}
.xd6-projects-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.xd6-project-card{min-width:0;overflow:hidden;background:#fff;color:#202126;border:1px solid #dddde2;border-radius:10px;transition:transform .2s,box-shadow .2s}
.xd6-project-card:hover{transform:translateY(-4px);box-shadow:0 12px 32px #0003}
.xd6-project-image{display:block;overflow:hidden;aspect-ratio:16/10;background:#242429}
.xd6-project-image img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .3s}
.xd6-project-card:hover img{transform:scale(1.04)}
.xd6-project-copy{padding:26px}
.xd6-project-copy h2{color:#202126;font-size:21px;font-weight:700;line-height:1.4;margin:0 0 14px;letter-spacing:normal;text-transform:none}
.xd6-project-copy h2 a{display:flex;align-items:start;justify-content:space-between;gap:16px;color:inherit}
.xd6-project-copy h2 a:hover{color:#b82b23}.xd6-project-arrow{flex-shrink:0;color:#b82b23;font-size:22px}
.xd6-project-copy p{margin:0;color:#5c6069;font-size:14px;line-height:1.8;overflow-wrap:anywhere}
.xd6-projects-empty{grid-column:1/-1;padding:32px;border:1px solid #333339;border-radius:10px;color:#c3c3ca;background:#1b1b20}
.xd6-projects-pagination{margin-top:36px;color:#c3c3ca}.xd6-projects-pagination svg{width:20px;height:20px}.xd6-projects-pagination a{color:#b82b23}
.xd6-projects-page a:focus-visible{outline:3px solid #d32b23;outline-offset:3px}
@media(max-width:900px){.xd6-projects-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.xd6-projects-page{padding-bottom:48px}.xd6-projects-container{width:calc(100% - 32px)}.xd6-projects-heading{padding:8px 0 28px;margin-bottom:28px}.xd6-projects-heading h1{font-size:36px}.xd6-projects-heading>p:last-child{font-size:15px}.xd6-projects-grid{grid-template-columns:minmax(0,1fr)}.xd6-project-copy{padding:24px 20px}}
@media(prefers-reduced-motion:reduce){.xd6-project-card,.xd6-project-image img{transition:none}.xd6-project-card:hover,.xd6-project-card:hover img{transform:none}}
</style>
